import { describe, expect, it } from "vitest";

const isValidId = (ids: readonly string[], id: string): boolean => ids.includes(id);

describe("isValidId", () => {
  it("accepts the first id at index 0 and rejects missing ids", () => {
    const ids = ["first", "second", "third"];
    expect(isValidId(ids, "first")).toBe(true);
    expect(isValidId(ids, "third")).toBe(true);
    expect(isValidId(ids, "unknown")).toBe(false);
  });
});
